class Solution:
    def maxValue(self, n: str, x: int) -> str:
        negative = n[0] == '-'
        i, res = 0, []
        if negative:
            i += 1
            res.append('-')
        find = False
        while i < len(n):
            num = int(n[i])
            if (negative and x < num) or (not negative and x > num):
                res.append(str(x))
                find = True
                break
            res.append(n[i])
            i += 1
        res.append(n[i:] if find else str(x))
        return ''.join(res)

class Solution {
    public String maxValue(String n, int x) {
        boolean negative = n.charAt(0) == '-';
        StringBuilder res = new StringBuilder();
        int i = 0;
        if (negative) {
            ++i;
            res.append("-");
        }
        boolean find = false;
        for (; i < n.length(); ++i) {
            int num = n.charAt(i) - '0';
            if ((negative && x < num) || (!negative && x > num)) {
                res.append(x);
                find = true;
                break;
            }
            res.append(n.charAt(i));
        }
        res.append(find ? n.substring(i) : x);
        return res.toString();
    }
}

/**
 * @param {string} n
 * @param {number} x
 * @return {string}
 */
 var maxValue = function(n, x) {
    let nums = [...n];
    let sign = 1, i = 0;
    if (nums[0] == '-') {
        sign = -1;
        i++;
    }
    while (i < n.length && (nums[i] - x) * sign >= 0) {
        i++;
    }
    nums.splice(i, 0, x);
    return nums.join('');
};
